const inquiryContext = $('Collect Inquiry Snapshot').first().json;
const inquiries = inquiryContext.inquiry_snapshot ?? [];
const deadLetters = $input.all().map((item) => item.json).filter((row) => row?.dead_letter_id);
const now = Date.now();
const countBy = (rows, field) => rows.reduce((acc, row) => {
  const key = row[field] || 'empty';
  acc[key] = (acc[key] || 0) + 1;
  return acc;
}, {});

const providerFailures = inquiries.filter((row) =>
  row.ack_status === 'failed' || row.slack_status === 'failed' || row.followup_status === 'failed');
const overdueFollowups = inquiries.filter((row) =>
  row.followup_status === 'scheduled' && row.followup_due_at && Date.parse(row.followup_due_at) < now);
const slowExecutions = inquiries.filter((row) => Number(row.processing_duration_ms || 0) > 10000);
const recoveryBacklog = inquiries.filter((row) =>
  ['pending_review', 'retrying', 'manual_review', 'attempt_limit_reached'].includes(row.reprocessing_status));
const unresolvedDeadLetters = deadLetters.filter((row) =>
  ['open', 'retrying', 'manual_review'].includes(row.status));
const stuckInquiries = inquiries.filter((row) => {
  if (!['intake_stored', 'reprocessing'].includes(row.processing_stage)) return false;
  const started = Date.parse(row.processing_started_at || row.stored_at || '');
  return Number.isFinite(started) && now - started > 15 * 60 * 1000;
});
const inquiryIds = new Set(inquiries.map((row) => row.inquiry_id));
const orphanDeadLetters = deadLetters.filter((row) => row.inquiry_id && !inquiryIds.has(row.inquiry_id));

const inquiryAttention = inquiries
  .filter((row) => row.processing_stage === 'unexpected_error' ||
    row.error_stage || providerFailures.includes(row) || overdueFollowups.includes(row) || recoveryBacklog.includes(row))
  .map((row) => ({
    type: 'inquiry', inquiry_id: row.inquiry_id, correlation_id: row.correlation_id,
    processing_stage: row.processing_stage, error_stage: row.error_stage || null,
    error_category: row.error_category || null, dead_letter_id: row.dead_letter_id || null,
    reprocessing_status: row.reprocessing_status,
    recommended_action: row.reprocessing_status === 'resolved' ? 'review_and_close_evidence' : 'investigate_inquiry',
  }));
const deadLetterAttention = unresolvedDeadLetters.map((row) => ({
  type: 'dead_letter', inquiry_id: row.inquiry_id || null, correlation_id: row.correlation_id || null,
  processing_stage: row.error_stage, error_stage: row.error_stage,
  error_category: row.error_category, dead_letter_id: row.dead_letter_id,
  reprocessing_status: row.status,
  recommended_action: row.status === 'open' ? 'review_retry_eligibility' : 'manual_resolution',
}));

let health = 'healthy';
const healthReasons = [];
if (providerFailures.length) healthReasons.push('provider_failures');
if (overdueFollowups.length) healthReasons.push('overdue_followups');
if (recoveryBacklog.length) healthReasons.push('recovery_backlog');
if (unresolvedDeadLetters.length) healthReasons.push('unresolved_dead_letters');
if (stuckInquiries.length) healthReasons.push('stuck_inquiries_over_15m');
if (orphanDeadLetters.length) healthReasons.push('orphan_dead_letters');
if (healthReasons.length) health = 'degraded';
if (recoveryBacklog.some((row) => row.reprocessing_status === 'attempt_limit_reached') ||
    unresolvedDeadLetters.some((row) => row.status === 'manual_review')) {
  health = 'critical';
  healthReasons.push('manual_intervention_required');
}

return [{ json: {
  generated_at: new Date().toISOString(),
  health,
  health_reasons: [...new Set(healthReasons)],
  summary: {
    total_inquiries: inquiries.length,
    total_dead_letters: deadLetters.length,
    provider_failures: providerFailures.length,
    overdue_followups: overdueFollowups.length,
    slow_executions_over_10s: slowExecutions.length,
    recovery_backlog: recoveryBacklog.length,
    unresolved_dead_letters: unresolvedDeadLetters.length,
    stuck_inquiries_over_15m: stuckInquiries.length,
    orphan_dead_letters: orphanDeadLetters.length,
  },
  breakdowns: {
    automation_status: countBy(inquiries, 'automation_status'),
    processing_stage: countBy(inquiries, 'processing_stage'),
    acknowledgment_status: countBy(inquiries, 'ack_status'),
    slack_status: countBy(inquiries, 'slack_status'),
    followup_status: countBy(inquiries, 'followup_status'),
    reprocessing_status: countBy(inquiries, 'reprocessing_status'),
    dead_letter_status: countBy(deadLetters, 'status'),
    error_category: countBy(deadLetters, 'error_category'),
  },
  attention_items: [...inquiryAttention, ...deadLetterAttention],
} }];

const ALERT_MODE = 'live';
return $input.all().map((item) => {
  const dashboard = item.json;
  const reasons = dashboard.health_reasons ?? [];
  const affectedIds = [...new Set(
    dashboard.attention_items.map((x) => x.dead_letter_id || x.correlation_id || x.inquiry_id).filter(Boolean),
  )].sort();
  const fingerprintParts = [dashboard.health, ...reasons.sort(), ...affectedIds];
  const fingerprint = fingerprintParts.join('|');
  const action = dashboard.health === 'healthy' ? 'no_alert' : ALERT_MODE === 'live' ? 'send' : 'preview';
  const attention = dashboard.attention_items.slice(0, 5).map((x) =>
    `• ${x.type}: ${x.inquiry_id || 'unlinked'} | ${x.error_category || x.processing_stage} | ${x.recommended_action}`);
  const text = [
    `*V4 operations health: ${dashboard.health.toUpperCase()}*`,
    `Reasons: ${reasons.join(', ') || 'none'}`,
    `Inquiries: ${dashboard.summary.total_inquiries}`,
    `Unresolved dead letters: ${dashboard.summary.unresolved_dead_letters}`,
    `Recovery backlog: ${dashboard.summary.recovery_backlog}`,
    `Stuck >15m: ${dashboard.summary.stuck_inquiries_over_15m}`,
    `Overdue follow-ups: ${dashboard.summary.overdue_followups}`,
    ...attention,
    dashboard.attention_items.length > 5 ? `…and ${dashboard.attention_items.length - 5} more attention item(s)` : null,
  ].filter(Boolean).join('\n');
  return { json: { ...dashboard, operational_alert: {
    mode: ALERT_MODE, action, severity: dashboard.health,
    fingerprint, text, prepared_at: new Date().toISOString(),
  } } };
});

const dashboard = $('Prepare Health Alert').first().json;
return $input.all().map((item) => ({ json: {
  ...dashboard,
  previous_alert_state: item.json?.alert_key ? item.json : null,
} }));

const COOLDOWN_MINUTES = 60;
return $input.all().map((item) => {
  const data = item.json;
  const current = data.operational_alert;
  const previous = data.previous_alert_state;
  const now = Date.now();
  let decision = 'suppress';
  let reason = 'healthy_no_open_incident';

  if (data.health === 'healthy') {
    if (previous?.status === 'open') { decision = 'send'; reason = 'incident_recovered'; }
  } else if (!previous || previous.status === 'resolved') {
    decision = 'send'; reason = 'new_incident';
  } else if (previous.fingerprint !== current.fingerprint) {
    decision = 'send'; reason = 'incident_changed';
  } else if (!previous.cooldown_until || Date.parse(previous.cooldown_until) <= now) {
    decision = 'send'; reason = 'cooldown_reminder';
  } else {
    reason = 'duplicate_during_cooldown';
  }

  let text = current.text;
  if (reason === 'incident_recovered') {
    text = `*V4 operations health: RECOVERED*\nPrevious incident is no longer active.\nPrevious severity: ${previous.severity}\nNotifications sent: ${previous.notification_count}`;
  }
  return { json: { ...data, alert_decision: {
    action: decision,
    reason,
    decided_at: new Date().toISOString(),
    cooldown_minutes: COOLDOWN_MINUTES,
    text,
  } } };
});

const originals = $('Decide Alert Notification').all();
return $input.all().map((item, index) => {
  const original = originals[index]?.json;
  if (!original) throw new Error(`Missing alert-decision context ${index}`);
  const failed = Boolean(item.json.error) || item.json.ok === false;
  return { json: { ...original, alert_delivery: {
    attempted: true,
    status: failed ? 'failed' : 'sent',
    provider_message_id: failed ? '' : String(item.json.ts ?? item.json.message?.ts ?? ''),
    error: failed ? (item.json.error?.message ?? item.json.error ?? 'Slack alert failed') : '',
    completed_at: new Date().toISOString(),
  } } };
});

return $input.all().map((item) => ({ json: { ...item.json, alert_delivery: {
  attempted: false,
  status: 'suppressed',
  provider_message_id: '',
  error: '',
  completed_at: new Date().toISOString(),
} } }));

return $input.all().map((item) => {
  const data = item.json;
  const previous = data.previous_alert_state;
  const decision = data.alert_decision;
  const delivery = data.alert_delivery;
  const now = delivery.completed_at;
  const sent = delivery.status === 'sent';
  const recovered = decision.reason === 'incident_recovered' && sent;
  const firstSeen = previous?.first_seen_at || now;
  const notificationCount = Number(previous?.notification_count || 0) + (sent ? 1 : 0);
  const cooldownUntil = sent && !recovered
    ? new Date(Date.parse(now) + decision.cooldown_minutes * 60 * 1000).toISOString()
    : previous?.cooldown_until || '';

  return { json: { ...data, alert_state_write: {
    alert_key: 'v4_operations_health',
    status: recovered || data.health === 'healthy' ? 'resolved' : 'open',
    severity: data.health,
    fingerprint: data.operational_alert.fingerprint,
    reasons_json: JSON.stringify(data.health_reasons ?? []),
    first_seen_at: firstSeen,
    last_seen_at: now,
    last_notified_at: sent ? now : previous?.last_notified_at || '',
    notification_count: notificationCount,
    cooldown_until: cooldownUntil,
    resolved_at: recovered ? now : previous?.resolved_at || '',
    last_message: decision.text,
    last_provider_message_id: sent ? delivery.provider_message_id : previous?.last_provider_message_id || '',
    last_error: delivery.error || '',
  } } };
});

const originals = $('Prepare Alert State Persistence').all();
return $input.all().map((item, index) => ({ json: {
  ...originals[index].json,
  alert_state_persisted: !item.json.error,
  persisted_row_id: item.json.id ?? null,
} }));
